UPDATE c SET EstadoPago=N'Pagada',IdRegistroPago=p.IdRegistroPago FROM dbo.CuotaMembresia c JOIN dbo.Pago p ON p.IdCuotaMembresia=c.IdCuotaMembresia WHERE p.IdRegistroPago BETWEEN 10172 AND 10239 AND p.Estado=N'Aprobado';
-- Se preservan los atrasos de las membresías que alcanzaron el límite; se quitan cuotas posteriores.
DELETE c FROM dbo.CuotaMembresia c JOIN dbo.Membresia m ON m.IdMembresia=c.IdMembresia WHERE m.Estado=0 AND c.EstadoPago=N'Pendiente' AND (c.FechaDesde>=DATEADD(DAY,1-DAY(CAST(GETDATE() AS date)),CAST(GETDATE() AS date)) OR (SELECT COUNT(*) FROM dbo.CuotaMembresia venc WHERE venc.IdMembresia=m.IdMembresia AND venc.EstadoPago=N'Pendiente' AND venc.FechaHasta<CAST(GETDATE() AS date))<2);
UPDATE m SET FechaVencimiento=ISNULL((SELECT MAX(c.FechaHasta) FROM dbo.CuotaMembresia c WHERE c.IdMembresia=m.IdMembresia AND c.EstadoPago=N'Pagada'),m.FechaInicio) FROM dbo.Membresia m WHERE m.Estado=0 AND NOT EXISTS(SELECT 1 FROM dbo.CuotaMembresia c WHERE c.IdMembresia=m.IdMembresia AND c.EstadoPago=N'Pendiente' AND c.FechaHasta<CAST(GETDATE() AS date));

-- Los comprobantes rechazados de cuotas antiguas se conservan; esas cuotas ya no se arrastran como deuda vigente.
UPDATE c SET EstadoPago = N'Anulada'
FROM dbo.CuotaMembresia c
INNER JOIN dbo.Pago p ON p.IdCuotaMembresia = c.IdCuotaMembresia AND p.Estado = N'Rechazado'
WHERE c.EstadoPago = N'Pendiente'
  AND c.FechaHasta < DATEADD(MONTH, -2, DATEADD(DAY, 1-DAY(CAST(GETDATE() AS date)), CAST(GETDATE() AS date)));

;WITH DeudasAntiguas AS (
    SELECT c.IdCuotaMembresia,
        ROW_NUMBER() OVER (PARTITION BY c.IdMembresia ORDER BY c.FechaHasta DESC, c.IdCuotaMembresia DESC) AS OrdenReciente
    FROM dbo.CuotaMembresia c
    INNER JOIN dbo.Membresia m ON m.IdMembresia = c.IdMembresia
    WHERE m.Estado = 0 AND c.EstadoPago = N'Pendiente' AND c.FechaHasta < CAST(GETDATE() AS date)
)
DELETE c FROM dbo.CuotaMembresia c
INNER JOIN DeudasAntiguas d ON d.IdCuotaMembresia = c.IdCuotaMembresia
WHERE d.OrdenReciente > 2
  AND NOT EXISTS (SELECT 1 FROM dbo.Pago p WHERE p.IdCuotaMembresia = c.IdCuotaMembresia);

-- El grupo de socios al día con membresías iniciadas el mes anterior completa su cuota del mes en curso.
UPDATE dbo.Membresia
SET FechaVencimiento = DATEADD(DAY, -1, DATEADD(MONTH, 1, DATEADD(DAY, 1-DAY(CAST(GETDATE() AS date)), CAST(GETDATE() AS date))))
WHERE IdMembresia BETWEEN 16 AND 28 AND Estado = 1;

