UPDATE c SET EstadoPago = N'Pagada', IdRegistroPago = p.IdRegistroPago
FROM dbo.CuotaMembresia c JOIN dbo.Pago p ON p.IdCuotaMembresia = c.IdCuotaMembresia
WHERE p.IdRegistroPago BETWEEN 10240 AND 10252 AND p.Estado = N'Aprobado';

-- Recuperación poscuarentena: una parte de las cuotas cobradas entre noviembre de 2020 y marzo de 2021 se percibe gradualmente durante los doce meses siguientes.
;WITH PagosRecuperacion AS (
    SELECT p.IdRegistroPago, p.Importe, c.FechaDesde,
        DATEDIFF(MONTH, c.FechaDesde, DATEADD(DAY, 1-DAY(CAST(GETDATE() AS date)), CAST(GETDATE() AS date))) AS MesesHastaActual,
        ROW_NUMBER() OVER (PARTITION BY CONVERT(char(7), c.FechaDesde, 120) ORDER BY p.Importe, p.IdRegistroPago) AS OrdenAscendente,
        ROW_NUMBER() OVER (PARTITION BY CONVERT(char(7), c.FechaDesde, 120) ORDER BY p.Importe DESC, p.IdRegistroPago) AS OrdenDescendente
    FROM dbo.Pago p
    INNER JOIN dbo.CuotaMembresia c ON c.IdCuotaMembresia = p.IdCuotaMembresia
    WHERE p.Estado = N'Aprobado'
      AND c.FechaDesde >= DATEADD(MONTH, -71, DATEADD(DAY, 1-DAY(CAST(GETDATE() AS date)), CAST(GETDATE() AS date)))
      AND c.FechaDesde < DATEADD(MONTH, -66, DATEADD(DAY, 1-DAY(CAST(GETDATE() AS date)), CAST(GETDATE() AS date)))
), PagosRecuperacionClasificados AS (
    SELECT *, CASE
        WHEN MesesHastaActual = 71 THEN CASE WHEN OrdenAscendente = 1 OR OrdenDescendente = 1 THEN 1 ELSE 0 END
        WHEN MesesHastaActual = 70 THEN CASE WHEN OrdenAscendente <= 2 OR OrdenDescendente = 1 THEN 1 ELSE 0 END
        WHEN MesesHastaActual = 69 THEN CASE WHEN OrdenAscendente <= 3 OR OrdenDescendente = 1 THEN 1 ELSE 0 END
        WHEN MesesHastaActual = 68 THEN CASE WHEN OrdenAscendente <= 4 OR OrdenDescendente = 1 THEN 1 ELSE 0 END
        WHEN MesesHastaActual = 67 THEN CASE WHEN OrdenAscendente <= 6 THEN 1 ELSE 0 END
        ELSE 0 END AS MantenerEnMes
    FROM PagosRecuperacion
), PagosRecuperacionExcedentes AS (
    SELECT IdRegistroPago,
        ROW_NUMBER() OVER (ORDER BY Importe DESC, IdRegistroPago) AS OrdenExcedente
    FROM PagosRecuperacionClasificados
    WHERE MantenerEnMes = 0
), FechasRecuperacion AS (
    SELECT IdRegistroPago, DATEADD(DAY, 4, FechaDesde) AS NuevaFecha
    FROM PagosRecuperacionClasificados
    WHERE MantenerEnMes = 1
    UNION ALL
    SELECT IdRegistroPago,
        DATEADD(DAY, 4, DATEADD(MONTH, ((OrdenExcedente - 1) % 12) - 66,
            DATEADD(DAY, 1-DAY(CAST(GETDATE() AS date)), CAST(GETDATE() AS date)))) AS NuevaFecha
    FROM PagosRecuperacionExcedentes
)
UPDATE p SET Fecha = f.NuevaFecha
FROM dbo.Pago p INNER JOIN FechasRecuperacion f ON f.IdRegistroPago = p.IdRegistroPago;

-- Los pagos del mes en curso quedan fechados en el día 1 a 5, nunca en el futuro.
UPDATE p SET Fecha = DATEADD(DAY,
    CASE WHEN DAY(CAST(GETDATE() AS date)) >= 5 THEN 4 ELSE DAY(CAST(GETDATE() AS date)) - 1 END,
    DATEADD(DAY, 1-DAY(CAST(GETDATE() AS date)), CAST(GETDATE() AS date)))
FROM dbo.Pago p
WHERE p.Estado = N'Aprobado'
  AND p.Fecha >= DATEADD(DAY, 1-DAY(CAST(GETDATE() AS date)), CAST(GETDATE() AS date))
  AND p.Fecha < DATEADD(MONTH, 1, DATEADD(DAY, 1-DAY(CAST(GETDATE() AS date)), CAST(GETDATE() AS date)));

