UPDATE p SET IdCuotaMembresia = c.IdCuotaMembresia
FROM dbo.Pago p JOIN dbo.CuotaMembresia c ON c.IdRegistroPago = p.IdRegistroPago
WHERE p.IdRegistroPago BETWEEN 14000 AND 14457;

-- Tarifas historicas por periodo: aumentos cada tres meses hasta 2022, cada dos meses en 2023-2024 y cada tres meses desde 2025.
;WITH PeriodosTarifa AS (
    SELECT c.IdCuotaMembresia, pl.Precio,
        81 - DATEDIFF(MONTH, c.FechaDesde, DATEADD(DAY,1-DAY(CAST(GETDATE() AS date)),CAST(GETDATE() AS date))) AS AntiguedadMeses
    FROM dbo.CuotaMembresia c
    INNER JOIN dbo.Membresia m ON m.IdMembresia = c.IdMembresia
    INNER JOIN dbo.[Plan] pl ON pl.IdPlan = m.IdPlan
), EtapasTarifa AS (
    SELECT *, CASE
        WHEN AntiguedadMeses >= 81 THEN 31
        WHEN AntiguedadMeses < 36 THEN FLOOR(CASE WHEN AntiguedadMeses < 0 THEN 0 ELSE AntiguedadMeses END / 3.0)
        WHEN AntiguedadMeses < 60 THEN 12 + FLOOR((AntiguedadMeses - 36) / 2.0)
        ELSE 24 + FLOOR((AntiguedadMeses - 60) / 3.0)
    END AS Etapa
    FROM PeriodosTarifa
)
UPDATE c SET Importe = ROUND((t.Precio * POWER(CAST(1.097 AS decimal(10,6)), t.Etapa - 31)) / 500.0, 0) * 500
FROM dbo.CuotaMembresia c INNER JOIN EtapasTarifa t ON t.IdCuotaMembresia = c.IdCuotaMembresia;
UPDATE p SET Importe = c.Importe
FROM dbo.Pago p INNER JOIN dbo.CuotaMembresia c ON c.IdCuotaMembresia = p.IdCuotaMembresia;
DELETE FROM dbo.Pago WHERE IdCuotaMembresia IS NULL;

-- Durante la recuperación poscuarentena algunos períodos se eximieron y se reembolsaron.
-- Se eligen socios inactivos distintos y se conserva cada pago reembolsado asociado a su cuota anulada.
;WITH Candidatos AS (
    SELECT TOP (5) p.IdRegistroPago
    FROM dbo.Pago p
    INNER JOIN dbo.CuotaMembresia c ON c.IdCuotaMembresia = p.IdCuotaMembresia AND c.IdRegistroPago = p.IdRegistroPago
    INNER JOIN dbo.Membresia m ON m.IdMembresia = c.IdMembresia
    WHERE p.IdRegistroPago BETWEEN 14000 AND 14457
      AND p.Estado = N'Aprobado' AND c.EstadoPago = N'Pagada' AND m.Estado = 0
      AND c.FechaDesde >= DATEADD(MONTH, -71, DATEADD(DAY, 1 - DAY(CAST(GETDATE() AS date)), CAST(GETDATE() AS date)))
      AND c.FechaDesde < DATEADD(MONTH, -70, DATEADD(DAY, 1 - DAY(CAST(GETDATE() AS date)), CAST(GETDATE() AS date)))
    ORDER BY p.IdRegistroPago
)
UPDATE p SET Estado = N'Reembolsado'
FROM dbo.Pago p INNER JOIN Candidatos x ON x.IdRegistroPago = p.IdRegistroPago;

