-- Parte de las cuotas del mes actual queda pendiente hasta el cierre del período; esto mantiene el ingreso parcial entre 70% y 90%.
;WITH PagosActuales AS (
    SELECT TOP 27 p.IdRegistroPago
    FROM dbo.Pago p
    INNER JOIN dbo.CuotaMembresia c ON c.IdCuotaMembresia = p.IdCuotaMembresia
    WHERE p.Estado = N'Aprobado'
      AND p.Fecha >= DATEADD(DAY,1-DAY(CAST(GETDATE() AS date)),CAST(GETDATE() AS date))
      AND p.Fecha < DATEADD(MONTH,1,DATEADD(DAY,1-DAY(CAST(GETDATE() AS date)),CAST(GETDATE() AS date)))
      AND c.FechaDesde >= DATEADD(DAY,1-DAY(CAST(GETDATE() AS date)),CAST(GETDATE() AS date))
      AND c.FechaDesde < DATEADD(MONTH,1,DATEADD(DAY,1-DAY(CAST(GETDATE() AS date)),CAST(GETDATE() AS date)))
      AND c.IdCuotaMembresia NOT BETWEEN 9197 AND 9209
    ORDER BY p.Importe DESC, p.IdRegistroPago
)
UPDATE p SET Estado = N'Pendiente'
FROM dbo.Pago p INNER JOIN PagosActuales a ON a.IdRegistroPago = p.IdRegistroPago;

UPDATE c SET EstadoPago = N'Pendiente', IdRegistroPago = NULL
FROM dbo.CuotaMembresia c
INNER JOIN dbo.Pago p ON p.IdRegistroPago = c.IdRegistroPago AND p.IdCuotaMembresia = c.IdCuotaMembresia
WHERE p.Estado = N'Pendiente'
  AND p.Fecha >= DATEADD(DAY,1-DAY(CAST(GETDATE() AS date)),CAST(GETDATE() AS date))
  AND p.Fecha < DATEADD(MONTH,1,DATEADD(DAY,1-DAY(CAST(GETDATE() AS date)),CAST(GETDATE() AS date)))
  AND c.FechaDesde >= DATEADD(DAY,1-DAY(CAST(GETDATE() AS date)),CAST(GETDATE() AS date))
  AND c.FechaDesde < DATEADD(MONTH,1,DATEADD(DAY,1-DAY(CAST(GETDATE() AS date)),CAST(GETDATE() AS date)));
