-- Recuperación después del invierno: redistribuye fechas de cobro entre meses, sin cambiar tarifas ni cuotas.
;WITH Candidatos AS (
    SELECT p.IdRegistroPago, p.Importe, ROW_NUMBER() OVER (PARTITION BY m.IdSocio ORDER BY p.Importe, p.IdRegistroPago) AS rn
    FROM dbo.Pago p
    INNER JOIN dbo.CuotaMembresia c ON c.IdCuotaMembresia = p.IdCuotaMembresia
    INNER JOIN dbo.Membresia m ON m.IdMembresia = c.IdMembresia
    WHERE p.Estado = N'Aprobado' AND c.EstadoPago = N'Pagada' AND c.IdRegistroPago = p.IdRegistroPago
      AND p.Fecha >= DATEADD(MONTH,-3,DATEADD(DAY,1-DAY(CAST(GETDATE() AS date)),CAST(GETDATE() AS date)))
      AND p.Fecha < DATEADD(MONTH,-2,DATEADD(DAY,1-DAY(CAST(GETDATE() AS date)),CAST(GETDATE() AS date)))
      AND c.FechaDesde >= DATEADD(MONTH,-3,DATEADD(DAY,1-DAY(CAST(GETDATE() AS date)),CAST(GETDATE() AS date)))
      AND c.FechaDesde < DATEADD(MONTH,-2,DATEADD(DAY,1-DAY(CAST(GETDATE() AS date)),CAST(GETDATE() AS date)))
      AND NOT EXISTS (SELECT 1 FROM dbo.Pago p2 INNER JOIN dbo.CuotaMembresia c2 ON c2.IdCuotaMembresia=p2.IdCuotaMembresia INNER JOIN dbo.Membresia m2 ON m2.IdMembresia=c2.IdMembresia WHERE m2.IdSocio=m.IdSocio AND p2.Estado=N'Aprobado' AND p2.Fecha>=DATEADD(MONTH,-2,DATEADD(DAY,1-DAY(CAST(GETDATE() AS date)),CAST(GETDATE() AS date))) AND p2.Fecha<DATEADD(MONTH,-1,DATEADD(DAY,1-DAY(CAST(GETDATE() AS date)),CAST(GETDATE() AS date))))
), Seleccion AS (SELECT TOP (3) IdRegistroPago FROM Candidatos WHERE rn=1 ORDER BY Importe,IdRegistroPago)
